sub bundle_scripts {
    my ($self, $target, $from, $to) = @_;

    my $dest_dirs = $self->dest_dirs_for($target);

    # Get the list of steps in the plan between $from and $to.
    # We need to find the 'from' and 'to' changepaths/keys to iterate.
    # Since we don't have direct access to the plan file parsing here without
    # more context or private methods, we assume the standard approach of
    # iterating through the plan or using the provided range.
    # However, looking at the signature and typical usage in Sqitch,
    # $from and $to are likely keys or paths.
    # The plan is usually stored in $self->plan_file.
    # We need to read the plan and filter steps.

    my $plan_file = $self->plan_file;
    return $self unless -e $plan_file;

    my @steps = $self->plan_steps($plan_file, $from, $to);

    # Iterate over each step in the plan
    for my $step (@steps) {
        my $step_type = $step->type;
        my $step_name = $step->name;

        # Determine the script type (deploy, revert, verify)
        # The step object should have a 'scripts' method or similar.
        # In Sqitch, steps have associated scripts based on their type.
        # A step can have deploy, revert, and verify scripts.

        my @script_types = ('deploy', 'revert', 'verify');

        for my $script_type (@script_types) {
            my $src_dir = $step->script_dir($script_type);
            my $dst_dir = $dest_dirs->{$script_type};

