    my ( $self, $name, @args ) = @_;

    # Validate that the change exists
    unless ( $self->contains($name) ) {
        hurl plan => __x(
            'Unknown change "{name}"',
            name => $name,
        );
    }

    # Find the most recent tag following the change
    my $tagged_name;
    my $change = $self->get($name);
    my $change_index = $self->index_of($change);

    # Check for tags after this change
    my $tag_index = undef;
    for my $tag ( $self->tags ) {
        my $tag_index_in_list = $self->index_of($tag);
        if ( $tag_index_in_list > $change_index ) {
            $tag_index = $tag_index_in_list;
            last;
        }
    }

    # If no tag found after the change, it's invalid
    unless ( defined $tag_index ) {
        hurl plan => __x(
            'Change "{name}" has no tag following it',
            name => $name,
        );
    }

    # Get the tag name
    my $tag = $self->change_at($tag_index);
    $tagged_name = $tag->format_name;

    # Modify the change to include the tag suffix
    $change->tag( $tagged_name );

    # Check dependencies again for the modified change (with the tag suffix)
    $self->_check_dependencies($change, 'rework');

    # Add the reworked change with the tag suffix
    $self->add(
        name      => $change->format_name,
        requires  => $change->requires,
        conflicts => $change->conflicts,
    );

    # Add a new tag for the reworked change
    $self->tag(
        name      => $tagged_name,
        change    => $change->format_name,
        note      => 'Rework',
    );

    return $self;
}
