sub insert_at {
    my ( $self, $line, $idx ) = @_;

    # Add the line to the list.
    my $list = $self->{list};
    splice @{ $list }, $idx, 0, $line;

    # Reindex.
    my $index = $self->{lookup};
    $index->{ $list->[$_] } = $_ for $idx..$#$list;
    return $self;
}
