    my @changes = @_;
    my $self = {
        list      => [],
        lookup    => {},
        count     => 0,
        last_tagged_at => undef,
    };
    bless $self, $class;

    for my $change (@changes) {
        push @{ $self->{list} }, $change;
        my $idx = $#$self->{list};

        my $name = $change->format_name;
        push @{ $self->{lookup}->{$name} }, $idx;
        $self->{lookup}->{$change->id} = $idx;

        for my $tag ($change->tags) {
            my $tag_name = $tag->format_name;
            $self->{lookup}->{$tag_name} = $idx;
            $self->{lookup}->{$tag->id} = $idx;
        }

        $self->{count}++;
    }

    $self->{lookup}->{'HEAD'} = [ $self->{count} - 1 ];
    $self->{lookup}->{'@HEAD'} = [ $self->{count} - 1 ];
    $self->{lookup}->{'ROOT'} = [ 0 ];
    $self->{lookup}->{'@ROOT'} = [ 0 ];

    return $self;
}
