    if ( $string =~ /^([^:]+):(.*)$/ ) {
        my $project = $1;
        my $rest = $2;

        # Validate project name (must not be empty after stripping leading whitespace if any, 
        # though spec implies strict format. We'll assume non-empty)
        $project =~ s/^\s+|\s+$//g;
        if ( !defined $project || $project eq '' ) {
            return undef;
