    return undef if !defined $string || $string eq '';

    # Format: [!]<project>:<change|tag>@<id>
    # OR: [!]<project>:<change|tag>
    # OR: <change|tag>@<id>
    # OR: <change|tag>
    # '!' indicates a conflict, otherwise it's a requirement.

    my $conflicts = 0;
    if ( substr( $string, 0, 1 ) eq '!' ) {
        $conflicts = 1;
        $string = substr( $string, 1 );
    }

    # Split on colon to separate project from the rest
    if ( $string =~ /^([^:]+):(.*)$/ ) {
        my $project = $1;
        my $rest = $2;

        # Validate project name (must not be empty after stripping leading whitespace if any, 
        # though spec implies strict format. We'll assume non-empty)
        $project =~ s/^\s+|\s+$//g;
        if ( !defined $project || $project eq '' ) {
            return undef;
        }

        # Now parse the rest: <change|tag>@<id> OR <change|tag>
        if ( $rest =~ /^([^@]+)@(.*)$/ ) {
            my $change_or_tag = $1;
            my $id = $2;

            $change_or_tag =~ s/^\s+|\s+$//g;
            $id =~ s/^\s+|\s+$//g;

            if ( !defined $change_or_tag || $change_or_tag eq '' ) {
